from fastapi.templating import Jinja2Templates
templates = Jinja2Templates(directory=TEMPLATES_DIR)

@router.get('/welcome')
def welcome_page(request: Request):
    if 'user_id' not in request.session:
        return RedirectResponse('/login', status_code=302)
    return templates.TemplateResponse('dashboard.html', {'request': request, 'username': request.session.get('username', 'Unknown')})

from slowapi import Limiter
from slowapi.util import get_remote_address
limiter = Limiter(key_func=get_remote_address)

@router.post('/login')
@limiter.limit('5/minute')
def login_post(request: Request, username: str = Form(None), password: str = Form(None)):
    return do_login(request, username, password)

@router.post('/logout')
def logout(request: Request, csrf_token: str = Form(...)):
    validate_csrf(request.session, csrf_token)
    request.session.clear()
    return RedirectResponse('/login', status_code=302)

